// Copies the event JSON Schemas from contracts/events into a TypeScript module, so the compiled
// package carries them and a service image does not need the contracts folder.
// Run it after a contract changes: npm run gen:events --workspace=@aforo/common
// A test (test/envelope.test.cjs) fails when the generated file drifts from the contracts.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const contracts = join(root, "contracts", "events");
const output = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "core", "envelope", "event-schemas.generated.ts");

const payloads = {
  "EventPublished.v1": "event-published.v1.schema.json",
  "SalesRulesConfigured.v1": "sales-rules-configured.v1.schema.json",
  "ReservationExpired.v1": "reservation-expired.v1.schema.json",
  "OrderPaid.v1": "order-paid.v1.schema.json",
};

const read = (file) => JSON.parse(readFileSync(join(contracts, file), "utf8"));

const lines = [
  "// Generated by scripts/gen-event-schemas.mjs from contracts/events/*.schema.json. Do not edit.",
  "",
  `export const envelopeSchema: Record<string, unknown> = ${JSON.stringify(read("envelope.schema.json"), null, 2)};`,
  "",
  "export const payloadSchemas: Record<string, Record<string, unknown>> = {",
  ...Object.entries(payloads).map(
    ([key, file]) => `  ${JSON.stringify(key)}: ${JSON.stringify(read(file), null, 2).replaceAll("\n", "\n  ")},`,
  ),
  "};",
  "",
];

writeFileSync(output, lines.join("\n"));
console.log(`wrote ${output}`);
